param([Parameter(Mandatory=$true)][string]$WorkRoot)
$ErrorActionPreference='Stop'
$area=Join-Path ([IO.Path]::GetFullPath($WorkRoot)) ('a-'+[guid]::NewGuid().ToString('N').Substring(0,8));[void][IO.Directory]::CreateDirectory($area)
$tool=Join-Path $PSScriptRoot 'ClaudeHistoryAutomatic.ps1';$archive=Join-Path $PSScriptRoot 'Archive-ClaudeHistoryIncremental.ps1'
$global:AutoTestOpen=$false;$global:AutoTestCalls=0;$global:AutoTestStartAt=0
function Get-Process {param($Name,$ErrorAction);if($Name-eq'Claude'){$global:AutoTestCalls++;if($global:AutoTestOpen-or($global:AutoTestStartAt-gt0-and$global:AutoTestCalls-ge$global:AutoTestStartAt)){[pscustomobject]@{Path='C:\fixture\Claude.exe'}}}}
$tests=New-Object System.Collections.Generic.List[object]
function Check($v,$m){if(-not$v){throw $m}}
function Refuses([scriptblock]$body){$threw=$false;try{&$body|Out-Null}catch{$threw=$true};Check $threw 'Refusal expected'}
function Case($name,[scriptblock]$body){$global:AutoTestOpen=$false;$global:AutoTestCalls=0;$global:AutoTestStartAt=0;try{&$body;$tests.Add([pscustomobject]@{Name=$name;Passed=$true;Detail=''})}catch{$tests.Add([pscustomobject]@{Name=$name;Passed=$false;Detail=$_.Exception.Message})}}
function Fixture {
 $base=Join-Path $area ([guid]::NewGuid().ToString('N').Substring(0,8));$sessions=Join-Path $base 'Claude\sessions';$projects=Join-Path $base '.claude\projects';$scopes=@();$paths=@()
 for($i=0;$i-lt4;$i++){$s=[guid]::NewGuid().ToString('D')+'/'+[guid]::NewGuid().ToString('D');$scopes+=$s;$paths+=Join-Path $sessions $s.Replace('/','\');[void][IO.Directory]::CreateDirectory($paths[-1])}
 [void][IO.Directory]::CreateDirectory((Join-Path $projects 'p\subagents'));[IO.File]::WriteAllText((Join-Path $projects 'p\subagents\agent.jsonl'),'fixture-subagent')
 [IO.File]::WriteAllText((Join-Path $paths[0] 'scheduled-tasks.json'),'DO NOT TOUCH TASKS');[IO.File]::WriteAllText((Join-Path $base 'Claude\config.json'),'DO NOT TOUCH GROUPS OR CONFIG')
 $f=[pscustomobject]@{Base=$base;Sessions=$sessions;Projects=$projects;Backup=(Join-Path $base 'backup');State=(Join-Path $base 'state');Scopes=$scopes;Paths=$paths;Config=(Join-Path $base 'config.json')}
 Config $f @();return $f
}
function Config($f,$exclude){
 $hashes=@{};foreach($name in @('Sync-ClaudeSessionsSafe.ps1','Sync-ClaudeSessionsAutomatic.ps1','Archive-ClaudeHistoryIncremental.ps1','ClaudeHistoryAutomatic.ps1')){$hashes[$name]=(Get-FileHash (Join-Path $PSScriptRoot $name)).Hash}
 @{Format='ClaudeOfflineAutomation-v1';SessionRoot=$f.Sessions;TranscriptRoot=$f.Projects;BackupRoot=$f.Backup;StateRoot=$f.State;Scopes=@($f.Scopes[0..2]);BaselineFileNames=@($exclude);ScriptSHA256=$hashes;AppUserModelId='Claude_fixture!Claude'}|ConvertTo-Json -Depth 6|Set-Content -LiteralPath $f.Config -Encoding utf8
}
function Chat($f,[int]$account=0,[string]$id=([guid]::NewGuid().ToString('D'))){
 $file=Join-Path $f.Paths[$account] ('local_'+$id+'.json');[IO.File]::WriteAllText($file,(@{sessionId=('local_'+$id);cliSessionId=$id;cwd=$f.Base;title='fixture';transcriptUnavailable=$false}|ConvertTo-Json -Compress))
 $tr=Join-Path $f.Projects ('p\'+$id+'.jsonl');if(-not[IO.File]::Exists($tr)){[IO.File]::WriteAllText($tr,'{"type":"user","text":"fixture"}')};return $file
}
function Run($f){&$tool -Mode Once -ConfigPath $f.Config}
function Capture($f){&$archive -SessionRoot $f.Sessions -TranscriptRoot $f.Projects -BackupRoot (Join-Path $f.Backup 'history')}
function State($f){$state=@{};foreach($p in @(Get-ChildItem (Join-Path $f.Base 'Claude'),$f.Projects -File -Recurse -Force)){$state[$p.FullName]=@{Hash=(Get-FileHash $p.FullName).Hash;Ticks=$p.LastWriteTimeUtc.Ticks}};return $state}
function Preserved($s){foreach($p in $s.Keys){Check ([IO.File]::Exists($p)) 'Original deleted';Check ((Get-FileHash $p).Hash-ceq$s[$p].Hash) 'Original changed';Check ([IO.File]::GetLastWriteTimeUtc($p).Ticks-eq$s[$p].Ticks) 'Original timestamp changed'}}
Case 'Preview writes nothing, with three registered accounts and one ignored scope' {$f=Fixture;$p=Chat $f;$s=State $f;$r=&$tool -Mode Preview -ConfigPath $f.Config;Check ($r.PlannedAdds-eq2-and-not(Test-Path $f.Backup)-and-not(Test-Path $f.State)) 'Preview mismatch';Preserved $s}
Case 'New conversation copied to two accounts after a verified full archive' {$f=Fixture;$p=Chat $f;$s=State $f;$r=Run $f;Check ($r.State-eq'Complete'-and$r.Detail.Added-eq2-and$r.Detail.Replaced-eq0-and$r.Detail.Deleted-eq0) 'Copy failed';Check (@(Get-ChildItem $f.Paths[3] -File).Count-eq0) 'Unregistered scope changed';Preserved $s}
Case 'Old conversations excluded by installation baseline' {$f=Fixture;$old=Chat $f;Config $f @([IO.Path]::GetFileName($old));$new=Chat $f 1;$s=State $f;$r=Run $f;Check ($r.Detail.Added-eq2-and-not(Test-Path (Join-Path $f.Paths[1] ([IO.Path]::GetFileName($old))))) 'Baseline propagated';Preserved $s}
Case 'Repeat run is idempotent and deduplicates all unchanged backup bytes' {$f=Fixture;$p=Chat $f;$first=Run $f;$s=State $f;$second=Run $f;$third=Run $f;Check ($second.Detail.Added-eq0-and$third.Detail.NewBackupBytes-eq0) 'Repeat wrote duplicates';Preserved $s}
Case 'Different existing metadata preserved and conflicting name not propagated' {$f=Fixture;$p=Chat $f;$id=([IO.Path]::GetFileNameWithoutExtension($p)).Substring(6);$other=Chat $f 1 $id;[IO.File]::AppendAllText($other,' ');$s=State $f;$r=Run $f;Check ($r.Detail.Added-eq0-and$r.Detail.Issues.Count-gt0) 'Conflict ignored';Preserved $s}
Case 'Deletion marker prevents automatic resurrection across accounts' {$f=Fixture;$p=Chat $f;$id=([IO.Path]::GetFileNameWithoutExtension($p)).Substring(6);[IO.File]::WriteAllText((Join-Path $f.Paths[1] ('deleted_'+$id)),'');$s=State $f;$r=Run $f;Check ($r.Detail.Added-eq0) 'Deleted chat propagated';Preserved $s}
Case 'Incomplete metadata skipped without changing any original' {$f=Fixture;$p=Chat $f;[IO.File]::WriteAllText($p,'{"cliSessionId":');$s=State $f;$r=Run $f;Check ($r.Detail.Added-eq0) 'Invalid propagated';Preserved $s}
Case 'Missing transcript skipped and original preserved' {$f=Fixture;$p=Chat $f;$id=([IO.Path]::GetFileNameWithoutExtension($p)).Substring(6);[IO.File]::Delete((Join-Path $f.Projects ('p\'+$id+'.jsonl')));$s=State $f;$r=Run $f;Check ($r.Detail.Added-eq0) 'Missing transcript propagated';Preserved $s}
Case 'App open causes wait with zero Claude writes and no archive' {$f=Fixture;$p=Chat $f;$s=State $f;$global:AutoTestOpen=$true;$r=Run $f;Check ($r.State-eq'WaitingForClaudeExit'-and-not(Test-Path $f.Backup)) 'App guard failed';Preserved $s}
Case 'App restart during archive refuses publication and retains incomplete work' {$f=Fixture;$p=Chat $f;$s=State $f;$global:AutoTestStartAt=7;Refuses {Run $f};Check (@(Get-ChildItem $f.Paths[1] -File).Count-eq0) 'Copied after restart';Preserved $s}
Case 'Full archive restores metadata, nested agents and attachments to a new folder' {$f=Fixture;$p=Chat $f;[IO.File]::WriteAllBytes((Join-Path $f.Projects 'p\asset.bin'),[byte[]]@(255,0,1,2));$s=State $f;$r=Capture $f;$dest=Join-Path $f.Base 'restore';$v=&$archive -Mode RestoreCopy -SnapshotPath $r.SnapshotPath -RestoreDestination $dest;Check ($v.Verified-and(Test-Path (Join-Path $dest 'data\projects\p\asset.bin'))) 'Restore failed';Preserved $s}
Case 'Changed transcript retained as a new version; both snapshots recover' {$f=Fixture;$p=Chat $f;$id=([IO.Path]::GetFileNameWithoutExtension($p)).Substring(6);$tr=Join-Path $f.Projects ('p\'+$id+'.jsonl');$r1=Capture $f;[IO.File]::AppendAllText($tr,"`ncontinued");$r2=Capture $f;Check ($r2.NewBytes-gt0) 'New version missing';foreach($r in @($r1,$r2)){$v=&$archive -Mode RestoreCopy -SnapshotPath $r.SnapshotPath -RestoreDestination (Join-Path $f.Base ([guid]::NewGuid().ToString('N')));Check $v.Verified 'Version not recoverable'}}
Case 'Corrupt stored blob blocks further sync and is never overwritten' {$f=Fixture;$p=Chat $f;$r=Capture $f;$blob=Get-ChildItem (Join-Path $f.Backup 'history\blobs') -File|Select-Object -First 1;[IO.File]::WriteAllText($blob.FullName,'corrupt');$s=State $f;$hash=(Get-FileHash $blob.FullName).Hash;Refuses {Run $f};Check ((Get-FileHash $blob.FullName).Hash-ceq$hash) 'Corrupt blob replaced';Check (@(Get-ChildItem $f.Paths[1] -File).Count-eq0) 'Published without backup';Preserved $s}
Case 'Incomplete snapshot rejected before restore creates a folder' {$f=Fixture;$p=Chat $f;$r=Capture $f;[IO.File]::Delete((Join-Path $r.SnapshotPath 'COMPLETE.json'));$dest=Join-Path $f.Base 'restore';Refuses {&$archive -Mode RestoreCopy -SnapshotPath $r.SnapshotPath -RestoreDestination $dest};Check (-not(Test-Path $dest)) 'Restore created prematurely'}
Case 'Existing restore destination refused and protected' {$f=Fixture;$p=Chat $f;$r=Capture $f;$s=State $f;Refuses {&$archive -Mode RestoreCopy -SnapshotPath $r.SnapshotPath -RestoreDestination $f.Projects};Preserved $s}
Case 'Task files and group config excluded from archives and unchanged' {$f=Fixture;$p=Chat $f;$s=State $f;$r=Run $f;$m=Get-Content (Join-Path $r.Detail.Snapshot 'manifest.json') -Raw|ConvertFrom-Json;Check (@($m.Files|Where-Object {$_.RelativePath-match'scheduled-tasks|config.json'}).Count-eq0) 'Forbidden data archived';Preserved $s}
Case 'Concurrent cycle lock blocks second writer' {$f=Fixture;$p=Chat $f;[void][IO.Directory]::CreateDirectory($f.State);$lock=[IO.File]::Open((Join-Path $f.State '.cycle.lock'),'OpenOrCreate','ReadWrite','None');$s=State $f;try{Refuses {Run $f}}finally{$lock.Dispose()};Preserved $s}
Case 'Concurrent archive lock blocks second archive' {$f=Fixture;$p=Chat $f;$root=Join-Path $f.Backup 'history';[void][IO.Directory]::CreateDirectory($root);$lock=[IO.File]::Open((Join-Path $root '.archive.lock'),'OpenOrCreate','ReadWrite','None');$s=State $f;try{Refuses {Capture $f}}finally{$lock.Dispose()};Preserved $s}
Case 'Changed integrity pin blocks execution before data writes' {$f=Fixture;$p=Chat $f;$c=Get-Content $f.Config -Raw|ConvertFrom-Json;$c.ScriptSHA256.'Archive-ClaudeHistoryIncremental.ps1'=('0'*64);$c|ConvertTo-Json -Depth 6|Set-Content $f.Config -Encoding utf8;$s=State $f;Refuses {Run $f};Check (-not(Test-Path $f.Backup)) 'Archive unexpectedly created';Preserved $s}
Case 'Backup inside Claude data refused' {$f=Fixture;$p=Chat $f;$c=Get-Content $f.Config -Raw|ConvertFrom-Json;$c.BackupRoot=Join-Path $f.Sessions 'unsafe';$c|ConvertTo-Json -Depth 6|Set-Content $f.Config -Encoding utf8;$s=State $f;Refuses {Run $f};Preserved $s}
Case 'Path traversal manifest rejected even with recomputed manifest hash' {$f=Fixture;$p=Chat $f;$r=Capture $f;$mp=Join-Path $r.SnapshotPath 'manifest.json';$m=Get-Content $mp -Raw|ConvertFrom-Json;$m.Files[0].RelativePath='data/projects/../../escape';$m|ConvertTo-Json -Depth 7|Set-Content $mp -Encoding utf8;@{Status='Complete';ManifestSHA256=(Get-FileHash $mp).Hash.ToLowerInvariant()}|ConvertTo-Json|Set-Content (Join-Path $r.SnapshotPath 'COMPLETE.json') -Encoding utf8;Refuses {&$archive -Mode Verify -SnapshotPath $r.SnapshotPath}}
Case 'A newly started conversation in each account reaches the other two' {$f=Fixture;for($i=0;$i-lt3;$i++){$p=Chat $f $i;$s=State $f;$r=Run $f;Check ($r.Detail.Added-eq2) 'New account not shared';Preserved $s};foreach($path in $f.Paths[0..2]){Check (@(Get-ChildItem $path -File -Filter 'local_*.json').Count-eq3) 'Incomplete sharing'}}
Case 'Pause also blocks manual cycle and preserves every file' {$f=Fixture;$p=Chat $f;[void][IO.Directory]::CreateDirectory($f.State);[IO.File]::WriteAllText((Join-Path $f.State 'PAUSE'),'');$s=State $f;$r=Run $f;Check ($r.State-eq'Paused'-and-not(Test-Path $f.Backup)) 'Pause ignored';Preserved $s}
Case 'Protected launcher activates the app only after verified archive and copy' {
 $f=Fixture;$p=Chat $f;$s=State $f;$global:AutoTestLaunched=$false
 function Start-Process {param($FilePath,$ArgumentList);$global:AutoTestLaunched=($ArgumentList-ceq'shell:AppsFolder\Claude_fixture!Claude');Check (@(Get-ChildItem $f.Paths[1] -Filter 'local_*.json').Count-eq1) 'Launched before copy'}
 $r=&$tool -Mode Launch -ConfigPath $f.Config 6>$null;Check ($global:AutoTestLaunched-and$r.State-eq'Complete') 'Protected launch did not complete';Preserved $s
}
Case 'Metadata created after a snapshot is never published using that old snapshot' {$f=Fixture;$old=Chat $f;$r=Capture $f;$new=Chat $f;$s=State $f;$copy=&(Join-Path $PSScriptRoot 'Sync-ClaudeSessionsAutomatic.ps1') -Mode Apply -SessionRoot $f.Sessions -TranscriptRoot $f.Projects -Scopes $f.Scopes[0..2] -BackupRoot (Join-Path $f.Backup 'meta') -ExcludeFileNames @([IO.Path]::GetFileName($old)) -RequiredSnapshotPath $r.SnapshotPath -Confirm:$false;Check ($copy.AddedCount-eq0) 'Unbacked metadata published';Preserved $s}
Case 'Transcript changed after a snapshot prevents publication' {$f=Fixture;$p=Chat $f;$r=Capture $f;$id=([IO.Path]::GetFileNameWithoutExtension($p)).Substring(6);[IO.File]::AppendAllText((Join-Path $f.Projects ('p\'+$id+'.jsonl')),'continued');$s=State $f;$copy=&(Join-Path $PSScriptRoot 'Sync-ClaudeSessionsAutomatic.ps1') -Mode Apply -SessionRoot $f.Sessions -TranscriptRoot $f.Projects -Scopes $f.Scopes[0..2] -BackupRoot (Join-Path $f.Backup 'meta') -RequiredSnapshotPath $r.SnapshotPath -Confirm:$false;Check ($copy.AddedCount-eq0) 'Unbacked transcript version published';Preserved $s}
Case 'Cycle remains pending if a source changes between backup and publication' {
 $f=Fixture;$p=Chat $f;$global:AutoTestMutated=$false;$global:AutoTestMutatePath=$p
 function Get-FileHash {param($LiteralPath,$Path,$Algorithm);$target=if($LiteralPath){$LiteralPath}else{$Path};$r=Microsoft.PowerShell.Utility\Get-FileHash -LiteralPath $target -Algorithm SHA256;if(-not$global:AutoTestMutated-and[IO.Path]::GetFileName($target)-eq'manifest.json'){[IO.File]::AppendAllText($global:AutoTestMutatePath,' ');$global:AutoTestMutated=$true};return $r}
 Refuses {Run $f};Check ($global:AutoTestMutated-and@(Get-ChildItem $f.Paths[1] -Filter 'local_*.json').Count-eq0) 'Unsafe completion after source changed'
}
$result=[pscustomobject]@{Runtime=$PSVersionTable.PSVersion.ToString();TestRoot=$area;Passed=@($tests|Where-Object Passed).Count;Failed=@($tests|Where-Object {-not$_.Passed}).Count;Tests=$tests.ToArray()}
$result|ConvertTo-Json -Depth 7
if($result.Failed-gt0){exit 1}
